def validate_row(row):
    lesson_id = row.get('lesson_id', '').strip()
    if not lesson_id:
        return {'ok': False, 'error': 'missing_lesson_id'}
    return {'ok': True, 'lesson_id': lesson_id}

def test_missing_lesson_id_has_stable_error():
    result = validate_row({'lesson_id': '   '})
    assert result == {'ok': False, 'error': 'missing_lesson_id'}

def test_valid_lesson_id_is_trimmed():
    result = validate_row({'lesson_id': ' loops '})
    assert result == {'ok': True, 'lesson_id': 'loops'}

test_missing_lesson_id_has_stable_error()
test_valid_lesson_id_is_trimmed()
print('two deterministic importer checks passed')

