def score_status(score):
    return 'pass' if score >= 70 else 'review'

def test_boundary_score_passes():
    assert score_status(70) == 'pass'

def test_score_below_boundary_needs_review():
    assert score_status(69) == 'review'

test_boundary_score_passes()
test_score_below_boundary_needs_review()
print('score boundary checked')
